func testAccCheckVertexAIModelDevelopmentClusterDestroyProducer(t *testing.T) func(s *terraform.State) error {
	return func(s *terraform.State) error {
		for name, rs := range s.RootModule().Resources {
			if rs.Type != "google_vertex_ai_model_development_cluster" {
				continue
			}
			if strings.HasPrefix(name, "data.") {
				continue
			}

			config := acctest.GoogleProviderConfig(t)
			url, err := tpgresource.ReplaceVarsForTest(config, rs, transport_tpg.BaseUrl(vertexai.Product, config)+"projects/{{project}}/locations/{{region}}/modelDevelopmentClusters/{{model_development_cluster_id}}")
			if err != nil {
				return err
			}
			if strings.Contains(url, "{{region}}") {
				return fmt.Errorf("failed to qualify endpoint for a resource with a regionalized endpoint %s", url)
			}

			billingProject := ""

			if config.BillingProject != "" {
				billingProject = config.BillingProject
			}

			_, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   billingProject,
				RawURL:    url,
				UserAgent: config.UserAgent,
			})
			if err == nil {
				return fmt.Errorf("VertexAIModelDevelopmentCluster still exists at %s", url)
			}
		}

		return nil
	}
}
